import{_ as r,C as i,o as a,c as o,ag as s,E as n}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"History","description":"Retained Specification receipts, withdrawn epochs, and immutable Provider releases.","frontmatter":{"title":"History","description":"Retained Specification receipts, withdrawn epochs, and immutable Provider releases."},"headers":[],"relativePath":"docs/history.md","filePath":"docs/history.md"}'),d={name:"docs/history.md"};function c(l,e,h,p,u,m){const t=i("StatusNote");return a(),o("div",null,[e[0]||(e[0]=s('<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h1><p>This page is historical evidence, not a second version model. Current readers should start with the <a href="/docs/versions.html">four-stream version model</a>.</p><h2 id="specification-receipt-—-historical-evidence-only" tabindex="-1">Specification receipt — historical evidence only <a class="header-anchor" href="#specification-receipt-—-historical-evidence-only" aria-label="Permalink to &quot;Specification receipt — historical evidence only&quot;">​</a></h2><p>The numbered <strong>Specification 1.1</strong> receipt records one immutable snapshot of normative evidence. It remains useful when auditing an old decision or reproducing a historical build. It is not a current release train, does not promote a Form, and does not create a Host API <code>/v1.1</code> lane.</p><p>The pre-publication <strong>Specification 1.0</strong> identity was withdrawn. Neither number is a current user-facing version stream. The retained <a href="/spec/">Specification source</a> is grouped separately in navigation and carries the same historical notice on every old URL.</p><h2 id="provider-distributions" tabindex="-1">Provider distributions <a class="header-anchor" href="#provider-distributions" aria-label="Permalink to &quot;Provider distributions&quot;">​</a></h2><p>Provider packages remain installable under exact pins so existing state can be recovered or migrated without rewriting published identity:</p><table tabindex="0"><thead><tr><th>Release</th><th>Retained role</th></tr></thead><tbody><tr><td><code>3.0.0</code></td><td>Current Registry-published mapping for 31 Experimental Forms.</td></tr><tr><td><code>2.1.1</code></td><td>Historical Host API v1beta1 compatibility client.</td></tr><tr><td><code>2.0.0</code></td><td>Historical client for the withdrawn v1alpha2 epoch.</td></tr><tr><td><code>1.0.3</code></td><td>Historical Legacy client for the withdrawn v1alpha1 epoch.</td></tr></tbody></table><p>Old packages and resource identities are not reassigned to a new Form. Pin the release that owns existing state, then follow the <a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a>. There is no automatic migration.</p><h2 id="preserved-routes" tabindex="-1">Preserved routes <a class="header-anchor" href="#preserved-routes" aria-label="Permalink to &quot;Preserved routes&quot;">​</a></h2><p>The old routes are deliberately still addressable:</p><ul><li><code>/spec/</code> and its nested contract pages preserve the historical source tree.</li><li><code>/release/</code> preserves publication and migration evidence.</li><li><code>/docs/reference.html</code> remains the generated legacy reference projection.</li></ul><p>Each route now points back to the current version model from a historical banner. The current <a href="/docs/reference-landing.html">reference landing page</a> is the entry point for the live Provider surface.</p>',13)),n(t)])}const b=r(d,[["render",c]]);export{f as __pageData,b as default};
